select closed_date, initcap(premise_type) as premise, coalesce(nullif(package_type_raw, ''), 'Unspecified') as package, sale_total_rm, package_sessions_recorded as sessions, coalesce(initcap(billing_arrangement), 'One payment') as billing, coalesce(nullif(trim(sales_pic), ''), 'Not recorded') as salesperson, case when recorded_returning_client then 'Returning client' else 'New client' end as client_type, days_first_contact_to_close from `profound-keel-500007-s4.gold.sales_package_facts` where include_in_sale_count and closed_date is not null
